/**
 * 黄金矿工 - 钩子状态机
 * 管理钩子的各种状态和状态转换
 */

// 钩子状态枚举
enum HookState {
  IDLE = 'idle',           // 空闲状态，等待玩家操作
  SWINGING = 'swinging',   // 左右摆动
  SHOOTING = 'shooting',   // 发射出去
  RETRACTING = 'retracting', // 收回中
  CAUGHT = 'caught',       // 捕获到物体
  STUCK = 'stuck'          // 卡住（捕获到石头等）
}

// 钩子配置接口
interface HookConfig {
  swingSpeed: number;      // 摆动速度
  shootSpeed: number;      // 发射速度
  retractSpeed: number;    // 收回速度
  maxLength: number;       // 最大长度
  minAngle: number;        // 最小角度
  maxAngle: number;        // 最大角度
}

// 捕获物接口
interface CaughtObject {
  id: string;
  type: 'gold' | 'diamond' | 'stone' | 'bonus';
  value: number;
  weight: number;
  position: { x: number; y: number };
}

// 状态机类
class HookStateMachine {
  private currentState: HookState;
  private config: HookConfig;

  // 钩子属性
  private angle: number = 90;  // 当前角度（90 度为垂直向下）
  private length: number = 0;  // 当前长度
  private swingDirection: number = 1;  // 摆动方向：1 向右，-1 向左
  private caughtObject: CaughtObject | null = null;

  // 回调函数
  private onStateChange?: (from: HookState, to: HookState) => void;
  private onCatch?: (obj: CaughtObject) => void;
  private onScore?: (value: number) => void;

  constructor(config: HookConfig) {
    this.config = config;
    this.currentState = HookState.IDLE;
  }

  /**
   * 获取当前状态
   */
  getState(): HookState {
    return this.currentState;
  }

  /**
   * 状态转换
   */
  private transition(newState: HookState): boolean {
    const validTransitions: Record<HookState, HookState[]> = {
      [HookState.IDLE]: [HookState.SWINGING],
      [HookState.SWINGING]: [HookState.SHOOTING],
      [HookState.SHOOTING]: [HookState.RETRACTING, HookState.CAUGHT, HookState.STUCK],
      [HookState.RETRACTING]: [HookState.IDLE],
      [HookState.CAUGHT]: [HookState.RETRACTING],
      [HookState.STUCK]: [HookState.RETRACTING]
    };

    if (!validTransitions[this.currentState].includes(newState)) {
      console.warn(`Invalid transition: ${this.currentState} -> ${newState}`);
      return false;
    }

    const oldState = this.currentState;
    this.currentState = newState;

    if (this.onStateChange) {
      this.onStateChange(oldState, newState);
    }

    return true;
  }

  /**
   * 开始摆动（游戏开始或回合开始）
   */
  startSwinging(): void {
    if (this.currentState === HookState.IDLE) {
      this.angle = 90;
      this.length = 0;
      this.transition(HookState.SWINGING);
    }
  }

  /**
   * 更新摆动状态
   */
  updateSwing(deltaTime: number): void {
    if (this.currentState !== HookState.SWINGING) return;

    this.angle += this.config.swingSpeed * this.swingDirection * deltaTime;

    // 边界检测，改变方向
    if (this.angle >= this.config.maxAngle) {
      this.angle = this.config.maxAngle;
      this.swingDirection = -1;
    } else if (this.angle <= this.config.minAngle) {
      this.angle = this.config.minAngle;
      this.swingDirection = 1;
    }
  }

  /**
   * 发射钩子（玩家按下按键）
   */
  shoot(): void {
    if (this.currentState === HookState.SWINGING) {
      this.transition(HookState.SHOOTING);
    }
  }

  /**
   * 更新发射状态
   */
  updateShoot(deltaTime: number): void {
    if (this.currentState !== HookState.SHOOTING) return;

    this.length += this.config.shootSpeed * deltaTime;

    // 检测是否达到最大长度
    if (this.length >= this.config.maxLength) {
      this.transition(HookState.RETRACTING);
    }

    // 检测碰撞（由外部调用）
  }

  /**
   * 检测到碰撞
   */
  onCollision(obj: CaughtObject): void {
    if (this.currentState !== HookState.SHOOTING) return;

    this.caughtObject = obj;

    if (obj.type === 'stone' || obj.weight > 100) {
      // 捕获到重物（石头）
      this.transition(HookState.STUCK);
    } else {
      // 捕获到普通宝物
      this.transition(HookState.CAUGHT);
    }

    if (this.onCatch) {
      this.onCatch(obj);
    }
  }

  /**
   * 开始收回
   */
  startRetract(): void {
    if (
      this.currentState === HookState.RETRACTING ||
      this.currentState === HookState.CAUGHT ||
      this.currentState === HookState.STUCK
    ) {
      this.transition(HookState.RETRACTING);
    }
  }

  /**
   * 更新收回状态
   */
  updateRetract(deltaTime: number): boolean {
    if (this.currentState !== HookState.RETRACTING) return false;

    // 根据捕获物重量调整收回速度
    let speed = this.config.retractSpeed;
    if (this.caughtObject) {
      speed /= (1 + this.caughtObject.weight / 100);
    }

    this.length -= speed * deltaTime;

    // 完全收回
    if (this.length <= 0) {
      this.length = 0;

      // 计算得分
      if (this.caughtObject && this.currentState !== HookState.STUCK) {
        if (this.onScore) {
          this.onScore(this.caughtObject.value);
        }
      }

      this.caughtObject = null;
      this.transition(HookState.IDLE);
      return true;  // 回合结束
    }

    return false;
  }

  /**
   * 获取钩子尖端位置
   */
  getTipPosition(): { x: number; y: number } {
    const rad = (this.angle * Math.PI) / 180;
    return {
      x: Math.sin(rad) * this.length,
      y: Math.cos(rad) * this.length
    };
  }

  /**
   * 重置钩子
   */
  reset(): void {
    this.currentState = HookState.IDLE;
    this.angle = 90;
    this.length = 0;
    this.caughtObject = null;
  }

  // Setter for callbacks
  setStateChangeCallback(cb: (from: HookState, to: HookState) => void): void {
    this.onStateChange = cb;
  }

  setCatchCallback(cb: (obj: CaughtObject) => void): void {
    this.onCatch = cb;
  }

  setScoreCallback(cb: (value: number) => void): void {
    this.onScore = cb;
  }
}

export { HookState, HookConfig, CaughtObject, HookStateMachine };

