// 使用示例
const hook = new HookStateMachine({
  swingSpeed: 60,
  shootSpeed: 300,
  retractSpeed: 200,
  maxLength: 800,
  minAngle: 30,
  maxAngle: 150
});

// 游戏循环中
function gameLoop(deltaTime: number) {
  if (hook.getState() === HookState.SWINGING) {
    hook.updateSwing(deltaTime);
  } else if (hook.getState() === HookState.SHOOTING) {
    hook.updateShoot(deltaTime);
  } else if (hook.getState() === HookState.RETRACTING) {
    hook.updateRetract(deltaTime);
  }
}
